using UnityEngine;

public sealed class GridShiftPlayerAppearance:MonoBehaviour {
 PlayerMovement player;Renderer[] originals;bool[] states;GameObject avatar;int revision=-1;int cameraMask;bool masked;
 void Start(){player=GetComponent<PlayerMovement>();var list=new System.Collections.Generic.List<Renderer>();foreach(var r in GetComponentsInChildren<Renderer>(true))if(!r.transform.IsChildOf(player.CameraTransform))list.Add(r);originals=list.ToArray();states=new bool[originals.Length];for(int i=0;i<originals.Length;i++)states[i]=originals[i].enabled;Refresh();}
 void Update(){if(revision!=GridShiftCharacter.Revision)Refresh();}
 public void Refresh(){if(player==null||originals==null)return;revision=GridShiftCharacter.Revision;var data=GridShiftCharacter.Current;var catalog=Resources.Load<GridShiftAvatarCatalog>("GridShiftAvatarCatalog");if(avatar!=null){avatar.SetActive(false);Destroy(avatar);avatar=null;}bool custom=data.model>=0&&catalog!=null&&catalog.models!=null&&catalog.models.Length>0;for(int i=0;i<originals.Length;i++)if(originals[i]!=null)originals[i].enabled=states[i]&&!custom;
  if(custom){var source=GridShiftSceneTemplates.Find(gameObject.scene,"avatar-"+data.model)??catalog.models[Mathf.Clamp(data.model,0,catalog.models.Length-1)];avatar=Instantiate(source,transform,false);avatar.name="Player customized appearance";foreach(var t in avatar.GetComponentsInChildren<Transform>(true))t.gameObject.layer=8;foreach(var c in avatar.GetComponentsInChildren<Collider>())c.enabled=false;ApplyColors(avatar,data);var animator=avatar.GetComponentInChildren<Animator>();if(animator!=null)player.BindAppearance(animator);}
  var camera=player.CameraTransform.GetComponent<Camera>();if(camera!=null){if(custom&&!masked){cameraMask=camera.cullingMask;masked=true;camera.cullingMask&=~(1<<8);}else if(!custom&&masked){camera.cullingMask=cameraMask;masked=false;}}
 }
 public static void ApplyColors(GameObject model,GridShiftCharacterData data){foreach(var renderer in model.GetComponentsInChildren<Renderer>()){var materials=renderer.sharedMaterials;for(int i=0;i<materials.Length;i++){if(materials[i]==null)continue;bool skin=(materials[i].name.Contains("GS Skin")||materials[i].name.StartsWith("skin-")),cloth=(materials[i].name.Contains("GS Outfit")||materials[i].name.StartsWith("outfit-"));int choice=skin?data.skin:cloth?data.outfit:-1;if(choice<0)continue;var block=new MaterialPropertyBlock();renderer.GetPropertyBlock(block,i);var catalog=Resources.Load<GridShiftAvatarCatalog>("GridShiftAvatarCatalog");block.SetTexture("_BaseMap",catalog!=null&&catalog.toneTexture!=null?catalog.toneTexture:Texture2D.whiteTexture);block.SetColor("_BaseColor",skin?GridShiftCharacter.SkinColors[choice]:GridShiftCharacter.OutfitColors[choice]);renderer.SetPropertyBlock(block,i);}}}
 void OnDestroy(){if(masked&&player!=null&&player.CameraTransform!=null){var camera=player.CameraTransform.GetComponent<Camera>();if(camera!=null)camera.cullingMask=cameraMask;}}
}

